ON CONFLICT ("name") DO UPDATE SET "sourceUrl" = COALESCE("PriceWatch"."sourceUrl", EXCLUDED."sourceUrl");

SELECT COUNT(*) AS "jami", COUNT("sourceUrl") AS "sahifasi_bor" FROM "PriceWatch";
